<?php declare(strict_types=1); use App\Core\Csrf; require __DIR__.'/header.php'; ?>
<div class="admin-title"><div><p class="eyebrow">CADASTROS</p><h1><?= e(ucfirst($entity)) ?></h1></div><a class="btn btn-primary" href="/admin/<?= e($entity) ?>/<?= e($config['new']) ?>">+ Adicionar</a></div><form class="admin-search" method="get"><label for="q">Buscar pelo nome</label><div><input id="q" name="q" maxlength="120" value="<?= e($search) ?>"><button class="btn" type="submit">Buscar</button></div></form><div class="admin-table"><table><thead><tr><th>Nome</th><th>Status</th><th>Última alteração</th><th>Ações</th></tr></thead><tbody><?php foreach($result['rows'] as $row): $id=(int)$row[$config['id']]; ?><tr><td><a href="/admin/<?= e($entity) ?>/<?= $id ?>/editar"><?= e($row['nome']) ?></a><?php if(isset($row['slug'])): ?><small><?= e($row['slug']) ?></small><?php endif ?></td><td><span class="status-tag <?= $row[$config['status']]?'is-active':'' ?>"><?= $row[$config['status']]?'Ativo':'Inativo' ?></span></td><td><?= e((new DateTimeImmutable($row['atualizado_em']))->format('d/m/Y H:i')) ?></td><td><div class="table-actions"><a class="btn btn-sm" href="/admin/<?= e($entity) ?>/<?= $id ?>/editar">Editar</a><form method="post" action="/admin/<?= e($entity) ?>/<?= $id ?>/status" data-confirm="Confirmar alteração de status?"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><button class="btn btn-sm" type="submit"><?= $row[$config['status']]?'Desativar':'Ativar' ?></button></form></div></td></tr><?php endforeach ?><?php if(!$result['rows']): ?><tr><td colspan="4">Nenhum registro encontrado. Ajuste a busca ou adicione um cadastro.</td></tr><?php endif ?></tbody></table></div><nav class="admin-pagination" aria-label="Paginação"><span><?= (int)$result['total'] ?> registros · Página <?= $page ?></span><?php if($page>1): ?><a class="btn btn-sm" href="?<?= e(http_build_query(['q'=>$search,'page'=>$page-1])) ?>">Anterior</a><?php endif ?><?php if($page*15<$result['total']): ?><a class="btn btn-sm" href="?<?= e(http_build_query(['q'=>$search,'page'=>$page+1])) ?>">Próxima</a><?php endif ?></nav><?php require __DIR__.'/footer.php'; ?>
